muscleBody=function(){const shapes=bodySide==='frente'?realisticFront:realisticBack;return `<svg class="realistic-atlas" viewBox="${bodySide==='frente'?220:120} 0 430 1024" role="group" aria-label="Mapa anatômico ilustrado · ${bodySide}"><image href="atlas-realista.png" x="${bodySide==='costas'?-768:0}" y="0" width="1536" height="1024"/>${Object.entries(shapes).map(([key,paths])=>`<g role="button" tabindex="0" aria-label="${muscleLibrary[key].label}" aria-pressed="${selectedMuscle===key}" class="realistic-region ${selectedMuscle===key?'selected':''}" data-muscle="${key}" onclick="chooseMuscle('${key}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();chooseMuscle('${key}')}"><title>${esc(muscleLibrary[key].label)}</title>${paths.map(d=>`<path d="${d}"/>`).join('')}</g>`).join('')}</svg><p class="note">Toque no grupo muscular para ver os exercícios. Ilustração original inspirada no estilo da referência.</p>`};
const realisticRender=render;render=function(){realisticRender();if(role==='personal'&&page==='treinos'&&trainingTab==='mapa'){const note=$('.body-panel>.note');if(note)note.textContent='Ilustração dos principais grupos musculares, com destaque em vermelho.';const normal=$('.key-normal'),selected=$('.key-selected');if(normal)normal.style.background='#bbb';if(selected)selected.style.background='#c72727'}};


